import type { SVGProps } from 'react';

/*
 * Page-edge decoration vectorised from the mockups (design/*.png): tiles, sprigs
 * and plants along the frame, one layer per colour. Positioned by FrameDecor.
 */

/** [Tailwind fill class, path data], painted in order: fills first, ink outlines last. */
type Layer = readonly [className: string, d: string];
type ArtProps = SVGProps<SVGSVGElement>;

/** Renders traced layers in a viewBox of the trace size (mockup pixels). */
function Art({ w, h, layers, ...props }: { w: number; h: number; layers: readonly Layer[] } & ArtProps) {
  return (
    <svg viewBox={`0 0 ${w} ${h}`} aria-hidden focusable="false" {...props}>
      {layers.map(([className, d], i) => (
        <path key={i} className={className} fillRule="evenodd" d={d} />
      ))}
    </svg>
  );
}

